 1	predicate IsEven(n: int)
 2	{
 3	    n % 2 == 0
 4	}
 5	
 6	predicate IsOdd(n: int)
 7	{
 8	    n % 2 != 0
 9	}
10	
11	method FirstEvenOddDifference(a: array<int>) returns (diff: int)
12	    requires a.Length >= 2
13	    requires exists i :: 0 <= i < a.Length && IsEven(a[i])
14	    requires exists i :: 0 <= i < a.Length && IsOdd(a[i])
15	    ensures exists i, j :: 0 <= i < (a.Length) - 1 && 0 <= j < a.Length && IsEven(a[i]) && IsOdd(a[j]) && diff == a[i] - a[j] &&
16	        (forall k :: 0 <= k < i ==> IsOdd(a[k])) && (forall k :: 0 <= k < j ==> IsEven(a[k]))
17	{
18	    var firstEven: int := -1;
19	    var firstOdd: int := -1;
20	
21	    for i := 0 to a.Length
22	        invariant 0 <= i <= a.Length
23	        invariant (firstEven == -1 || (0 <= firstEven < i && IsEven(a[firstEven])))
24	        invariant (firstOdd == -1 || (0 <= firstOdd < i && IsOdd(a[firstOdd])))
25	        invariant firstEven == -1 ==> (forall k :: 0 <= k < i ==> !IsEven(a[k]))
26	        invariant firstOdd == -1 ==> (forall k :: 0 <= k < i ==> !IsOdd(a[k]))
27	        invariant firstEven != -1 ==> (forall k :: 0 <= k < firstEven ==> IsOdd(a[k]))
28	        invariant firstOdd != -1 ==> (forall k :: 0 <= k < firstOdd ==> IsEven(a[k]))
29	    {
30	        if firstEven == -1 && IsEven(a[i])
31	        {
32	            firstEven := i;
33	        }
34	        if firstOdd == -1 && IsOdd(a[i])
35	        {
36	            firstOdd := i;
37	        }
38	        if firstEven != -1 && firstOdd != -1
39	        {
40	            break;
41	        }
42	    }
43	    diff := a[firstEven] - a[firstOdd];
44	}

